// ValidOutputFormats returns all valid output format values
func ValidOutputFormats() []string {
	return []string{string(OutputBlended), string(OutputByQuery), string(OutputByCollection)}
}

// Formatter handles output formatting with support for AXI, JSON and minimal modes.
type Formatter struct {
	JSON    bool // Output as JSON
	Minimal bool // Output in minimal/token-optimized mode
	AXI     bool // Output as TOON (AXI token-dense format)
	Writer  io.Writer
}

// IsValidOutputFormat checks if the given format string is valid
func IsValidOutputFormat(format string) bool {
	switch OutputFormat(format) {
	case OutputBlended, OutputByQuery, OutputByCollection:
		return true
	case "": // empty means default (blended)
		return true
	}
	return false
}

func TestFormatter_Print_JSON(t *testing.T) {
	var buf bytes.Buffer
	f := New(true, false, &buf)

	data := TestOutput{Name: "test", Count: 5}

	err := f.Print(data, nil)
	if err != nil {
		t.Fatalf("Print failed: %v", err)
	}

	output := buf.String()
	if !strings.Contains(output, "\"name\": \"test\"") {
		t.Errorf("Expected JSON output with name, got: %s", output)
	}
	if !strings.Contains(output, "\"count\": 5") {
		t.Errorf("Expected JSON output with count, got: %s", output)
	}
	// Should be pretty-printed (contains newlines)
	if !strings.Contains(output, "\n  ") {
		t.Errorf("Expected pretty-printed JSON, got: %s", output)
	}
}

// resetOutputGlobals restores the mode globals after a test, since the package
// shares them across every test that runs after it.
func resetOutputGlobals(t *testing.T) {
	t.Helper()
	t.Cleanup(func() {
		GlobalAXIOutput = false
		GlobalJSONOutput = false
		GlobalMinOutput = false
		output.SetDefaultAXI(false)
	})
}

// outputMode is one of the four ways a search command prints.
type outputMode struct {
	name       string
	json, min  bool
	axi        bool
	structured bool // stdout is JSON
}

func runRefs(ctx context.Context, symbol string, jsonOutput, minOutput bool) error {
	rs, cleanup, err := openRefStorage(ctx)
	if err != nil {
		return err
	}
	defer cleanup()

	return writeRefs(ctx, os.Stdout, os.Stderr, rs, symbol, jsonOutput, minOutput)
}

// resolveOutputMode publishes the output mode the parsed flags ask for.
func resolveOutputMode(cmd *cobra.Command) {
	GlobalJSONOutput = flagOn(cmd, "json")
	GlobalMinOutput = flagOn(cmd, "min")
	GlobalAXIOutput = !GlobalJSONOutput && !flagOn(cmd, "plain")
	output.SetDefaultAXI(GlobalAXIOutput)
}
